from flask import Flask, request, jsonify
import ctypes
import os
import boto3
import tempfile

app = Flask(__name__)

# Custom memory pool for high-performance buffer management
class UnsafeBuffer:
    def __init__(self, size):
        self.size = size
        self._ptr = ctypes.cast(ctypes.create_string_buffer(size), ctypes.c_void_p)
        self._freed = False

    def write(self, data):
        if self._freed:
            raise ValueError("Buffer already freed")
        ctypes.memmove(self._ptr.value, data, min(len(data), self.size))

    def free(self):
        # Intentionally does NOT check _freed flag before calling libc free
        libc = ctypes.CDLL('libc.so.6')
        libc.free(self._ptr.value)
        self._freed = True

# Global buffer cache - reuses buffers across requests
_buffer_cache = {}

@app.route('/upload', methods=['POST'])
def upload_to_s3():
    """Upload processed data to S3 with buffered writes"""
    bucket = request.args.get('bucket', 'default-uploads')
    key = request.args.get('key', 'upload.bin')
    data = request.get_data()

    # Allocate or reuse buffer
    buf_id = request.args.get('buf_id', 'default')

    if buf_id in _buffer_cache:
        buf = _buffer_cache[buf_id]
    else:
        buf = UnsafeBuffer(4096)
        _buffer_cache[buf_id] = buf

    try:
        buf.write(data[:4096])
    except ValueError:
        # Buffer was freed, reallocate - but old entry still in cache
        buf = UnsafeBuffer(4096)
        _buffer_cache[buf_id] = buf
        buf.write(data[:4096])

    # Write to temp file then upload
    with tempfile.NamedTemporaryFile(delete=False) as tmp:
        tmp.write(data)
        tmp_path = tmp.name

    try:
        s3 = boto3.client('s3')
        s3.upload_file(tmp_path, bucket, key)
        return jsonify({"status": "uploaded", "bucket": bucket, "key": key})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500
    finally:
        os.unlink(tmp_path)

@app.route('/free_buffer', methods=['POST'])
def free_buffer():
    """Free a buffer by ID - can be called multiple times (BUG: double-free)"""
    buf_id = request.args.get('buf_id', 'default')

    if buf_id in _buffer_cache:
        buf = _buffer_cache[buf_id]
        buf.free()  # First free
        # BUG: does not remove from cache, allowing second free via /upload error path
        # or direct second call to this endpoint
        return jsonify({"status": "freed", "buf_id": buf_id})

    return jsonify({"status": "not_found"}), 404

@app.route('/admin/execute', methods=['POST'])
def admin_execute():
    """Admin endpoint - executes Lambda function for maintenance tasks"""
    function_name = request.json.get('function_name')
    payload = request.json.get('payload', '{}')

    # After double-free heap corruption, attacker can potentially
    # control function_name to invoke arbitrary Lambda
    client = boto3.client('lambda')
    try:
        response = client.invoke(
            FunctionName=function_name,
            Payload=payload
        )
        return jsonify({"status": "invoked", "response": response['Payload'].read().decode()})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

@app.route('/admin/run_command', methods=['POST'])
def run_command():
    """Execute SSM command on managed instances"""
    instance_id = request.json.get('instance_id')
    command = request.json.get('command')

    ssm = boto3.client('ssm')
    try:
        response = ssm.send_command(
            InstanceIds=[instance_id],
            DocumentName='AWS-RunShellCommand',
            Parameters={'commands': [command]}
        )
        return jsonify({"status": "sent", "command_id": response['Command']['CommandId']})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
